    known_targets = upper_targets | lower_targets

    initial_scene = (
        a[30][0] == "S"
        and a[3][33] == "Y"
        and a[42][9] == "B"
    )

    if initial_scene and name == "UP":
        a = [list("b" * 63 + "Y") for _ in range(64)]
        a[63] = list("B" * 63 + "Y")

        for r, c in known_targets:
            tile(r, c, "Y")

        for c in range(21):
            tile(3, c, "S", "W")

        for r, c in upper_targets:
            tile(r, c, "Y")

        u = {(6, 4), (6, 8)} | {
            (7, c) for c in range(4, 9)
        }
        bar = {(r, 6) for r in range(10, 16)}

        for r, c in u | bar:
            tile(r, c, "B", "b")

        tile(0, 4, "c")
        tile(0, 8, "c")
        return finish()

    cells = black_cells()
    pieces = components(cells)

    mirror_rows = [
        r for r in range(21)
        if sum(a[3 * r][3 * c] == "S" for c in range(21)) >= 10
    ]
    mirror = mirror_rows[0] if mirror_rows else None

    post_scene = mirror == 3 and (
        a[18][33] == "Y"
        or a[30][39] == "Y"
        or a[33][33] == "Y"
    )

    targets = set(known_targets) if post_scene else set()
    for r in range(21):
        for c in range(21):
            if a[3 * r][3 * c] == "Y":
                targets.add((r, c))

    def background(r, c):
        if (r, c) in targets:
            return "Y"
        if mirror is not None and r == mirror:
            return "S"
        return "b"

    selected = [
        piece for piece in pieces
        if any(
            a[3 * r + 1][3 * c + 1] == "W"
            for r, c in piece
        )
    ]

