        "UP": (-1, 0),
        "DOWN": (1, 0),
        "LEFT": (0, -1),
        "RIGHT": (0, 1),
    }

    if name not in directions or not selected:
        return finish()

    piece = selected[0]
    dr, dc = directions[name]
    moved = {(r + dr, c + dc) for r, c in piece}

    if any(
        not (0 <= r < 21 and 0 <= c < 21)
        for r, c in moved
    ):
        return finish()

    stationary = cells - piece
    if moved & stationary:
        return finish()

    if mirror is not None:
        for r, c in piece:
            rr = 2 * mirror - r
            if 0 <= rr < 21 and a[3 * rr][3 * c] == "c":
                tile(rr, c, background(rr, c))

    for r, c in piece:
        # Uncovered targets are solid yellow, without white centers.
        tile(r, c, background(r, c))

    if mirror is not None:
        for r, c in moved:
            rr = 2 * mirror - r
            if 0 <= rr < 21 and (rr, c) not in stationary:
                center = "Y" if (rr, c) in targets else None
                tile(rr, c, "c", center)

    for r, c in moved:
        center = "Y" if (r, c) in targets else "W"
