def predict(board_lines, action):
    """Predict a complete 64x64 board using the inferred reflection rules."""
    board = list(board_lines)
    if len(board) != 64 or any(len(row) != 64 for row in board):
        raise ValueError("Expected 64 strings of length 64")

    if not isinstance(action, str):
        return board[:]
    action = action.strip().upper()
    if action not in {"UP", "DOWN", "LEFT", "RIGHT", "SPACE"}:
        return board[:]

    N = 21

    def images(cells, hy, vx):
        result = set()
        for r, c in cells:
            for rr, cc in (
                (r, c), (2 * hy - r, c),
                (r, 2 * vx - c), (2 * hy - r, 2 * vx - c)
            ):
                if 0 <= rr < N and 0 <= cc < N:
                    result.add((rr, cc))
        return result

    def components(cells):
        # Diagonal neighbors belong to the same observed piece.
        remaining = set(cells)
        result = []
        while remaining:
            seed = min(remaining)
            remaining.remove(seed)
            component = {seed}
            stack = [seed]
            while stack:
                r, c = stack.pop()
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        p = (r + dr, c + dc)
                        if p in remaining:
                            remaining.remove(p)
                            component.add(p)
                            stack.append(p)
            result.append(component)
        result.sort(key=lambda s: (len(s), sorted(s)))
        return result

    def render(pieces, targets, hy, vx, selection, moves):
        black = set().union(*pieces) if pieces else set()
        occupied = images(black, hy, vx)
        selected_piece = (
            pieces[selection - 2]
            if 2 <= selection < len(pieces) + 2 else set()
        )
        out = [["b"] * 64 for _ in range(64)]

        for r in range(N):
            for c in range(N):
                p = (r, c)
                target = p in targets
                if p in black:
                    fill, center = "B", "b"
                elif p in occupied:
                    fill, center = "c", "c"
                elif target:
                    fill, center = "Y", "Y"
                elif r == hy or c == vx:
                    fill, center = "S", "b"
                else:
                    fill, center = "b", "b"

                highlighted = (
                    (selection == 0 and r == hy)
                    or (selection == 1 and c == vx)
                    or p in selected_piece
                )
                if target:
                    center = "Y"
                elif highlighted:
                    center = "W"

                rr, cc = 3 * r, 3 * c
                for dr in range(3):
                    out[rr + dr][cc:cc + 3] = [fill] * 3
                out[rr + 1][cc + 1] = center

        out[63] = ["B"] * 64
        for r in range(64):
            out[r][63] = "O" if r < min(moves, 64) else "Y"
        return ["".join(row) for row in out]

    def next_puzzle():
        upper = {
            (3, 15), (3, 16), (3, 17),
            (4, 14), (4, 18),
            (5, 14), (6, 14), (7, 15),
        }
        lower = {(8, 18), (9, 17), (9, 18), (9, 19), (9, 20)}

        # The target layout is symmetric about row 11 and column 6.
        solved_upper = {(r + 12, c - 7) for r, c in upper}
        solved_lower = {(r + 4, c - 15) for r, c in lower}
        targets = images(solved_upper | solved_lower, 11, 6)
        return render([lower, upper], targets, 0, 7, 0, 0)

    tile = [[board[3*r][3*c] for c in range(N)] for r in range(N)]
    center = [
        [board[3*r + 1][3*c + 1] for c in range(N)]
        for r in range(N)
    ]

    hy = max(range(N), key=lambda r: sum(x == "S" for x in tile[r]))
    vx = max(
        range(N),
        key=lambda c: sum(tile[r][c] == "S" for r in range(N))
    )

    targets = {
        (r, c) for r in range(N) for c in range(N)
        if center[r][c] == "Y"
    }
    black = {
        (r, c) for r in range(N) for c in range(N)
        if tile[r][c] == "B"
    }
    whites = {
        (r, c) for r in range(N) for c in range(N)
        if center[r][c] == "W"
    }
    pieces = components(black)

    # Axis selections include white centers outside the black pieces.
    outside_whites = whites - black
    if outside_whites:
        h_score = sum(r == hy for r, c in outside_whites)
        v_score = sum(c == vx for r, c in outside_whites)
        selection = 0 if h_score >= v_score else 1
    elif whites and pieces:
        selected_index = max(
            range(len(pieces)),
            key=lambda i: len(pieces[i] & whites)
        )
        selection = selected_index + 2
    else:
        selection = 0

    moves = sum(row[63] == "O" for row in board)

    if action == "SPACE":
        selection = (selection + 1) % (len(pieces) + 2)
    else:
