def predict(board_lines, action):
    board = [list(row) for row in board_lines]
    if len(board) != 64 or any(len(row) != 64 for row in board):
        raise ValueError("Expected a 64x64 board")

    if not isinstance(action, str):
        return list(board_lines)
    action = action.strip().upper()
    directions = {
        "UP": (-3, 0),
        "DOWN": (3, 0),
        "LEFT": (0, -3),
        "RIGHT": (0, 3),
    }
    if action not in directions and action != "SPACE":
        return list(board_lines)

    moving = {
        (r, c)
        for r in range(1, 64)
        for c in range(64)
        if board[r][c] == "W"
    }
    if not moving:
        return list(board_lines)

    pending = list(moving)
    while pending:
        r, c = pending.pop()
        for nr, nc in ((r - 1, c), (r + 1, c),
                       (r, c - 1), (r, c + 1)):
            if (1 <= nr < 64 and 0 <= nc < 64
                    and (nr, nc) not in moving
                    and board[nr][nc] in ("W", "R")):
                moving.add((nr, nc))
                pending.append((nr, nc))

    top = min(r for r, c in moving)
    bottom = max(r for r, c in moving)
    left = min(c for r, c in moving)
    right = max(c for r, c in moving)

    red = [(r, c) for r, c in moving if board[r][c] == "R"]
    orientation = 0
    if red:
        if all(r >= bottom - 2 for r, c in red):
            orientation = 0
        elif all(c <= left + 2 for r, c in red):
            orientation = 1
        elif all(r <= top + 2 for r, c in red):
            orientation = 2
        elif all(c >= right - 2 for r, c in red):
            orientation = 3

    destination = {}
    for r, c in moving:
        if action == "SPACE":
            nr = top + c - left
            nc = left + bottom - r
        else:
            dr, dc = directions[action]
            nr, nc = r + dr, c + dc
        destination[(nr, nc)] = board[r][c]

    for r, c in destination:
        if not (1 <= r < 64 and 0 <= c < 64):
            return list(board_lines)
        if (r, c) not in moving and board[r][c] != "S":
            return list(board_lines)

    for r, c in moving:
        board[r][c] = "S"
    for (r, c), color in destination.items():
        board[r][c] = color

    phase = ((top - 11) // 3 + (left - 11) // 3 + orientation) % 2
    if phase:
        for c in range(16, 48):
            if board[0][c] == "c":
                board[0][c] = "W"
                break

    return ["".join(row) for row in board]

