        (0, 1, "R"),
        (1, 0, "p"), (1, 1, "p"), (1, 2, "p"),
        (2, 0, "p"), (2, 2, "p"),
        (3, 0, "p"), (3, 2, "p"),
        (4, 0, "p"),
        (4, 2, "p"), (4, 3, "p"), (4, 4, "p"),
        (4, 5, "p"),
        (5, 0, "p"), (5, 5, "p"), (5, 6, "R"),
    ]
    purple += [(6, x, "p") for x in range(6)]

    def pixels(template, origin):
        r0, c0 = origin
        for tr, tc, color in template:
            for rr in range(r0 + 3 * tr, r0 + 3 * tr + 3):
                for cc in range(c0 + 3 * tc, c0 + 3 * tc + 3):
                    yield rr, cc, color

    def paint(template, origin, override=None, preserve_join=False):
        for r, c, color in pixels(template, origin):
            if 0 <= r < 64 and 0 <= c < 64:
                if preserve_join and color == "R" and b[r][c] == "G":
                    continue
                b[r][c] = color if override is None else override

    def matches(template, origin, inactive=False):
        for r, c, color in pixels(template, origin):
            if not (1 <= r < 64 and 0 <= c < 64):
                return False
            actual = b[r][c]
            if inactive:
                if actual != "c":
                    return False
            elif actual != color and not (color == "R" and actual == "G"):
                return False
        return True

    def find(template, inactive=False):
        for r in range(2, 62, 3):
            for c in range(2, 62, 3):
                tr, tc, color = template[0]
                rr, cc = r + tr * 3, c + tc * 3
                if rr >= 64 or cc >= 64:
                    continue
                expected = "c" if inactive else color
                if b[rr][cc] != expected:
                    if inactive or color != "R" or b[rr][cc] != "G":
                        continue
                if matches(template, (r, c), inactive):
                    return r, c
        return None

    def find_active_yellow():
        exact = find(yellow)
        if exact is not None:
            return exact

        # Repair: recognize the body independently of terminal rendering.
        # Its five horizontal tiles form a 3-high, 15-wide Y rectangle.
        for r in range(4, 62):
            for c in range(3, 50):
                if b[r][c] != "Y":
                    continue
                if c > 0 and b[r][c - 1] == "Y":
                    continue
                if r > 1 and b[r - 1][c] == "Y":
                    continue
                if all(
                    b[rr][cc] == "Y"
                    for rr in range(r, r + 3)
                    for cc in range(c, c + 15)
                ):
                    return r - 3, c - 3
        return None

    def contains(template, origin, point):
        r, c = point
        r0, c0 = origin
        return any(
            r0 + 3 * tr <= r < r0 + 3 * tr + 3
            and c0 + 3 * tc <= c < c0 + 3 * tc + 3
            for tr, tc, _ in template
        )

    def move(template, origin, dr, dc):
        destination = origin[0] + dr, origin[1] + dc
        cells = list(pixels(template, destination))
        if any(
            not (1 <= r < 64 and 0 <= c < 64)
            for r, c, _ in cells
        ):
            return False
        paint(template, origin, "O")
        paint(template, destination)
        return True

    def result():
        return ["".join(row) for row in b]

    point = None
    if isinstance(action, str):
        text = action.strip()
        name = text.split("(", 1)[0].strip().upper()
        if name == "MOUSE":
            numbers = re.findall(r"-?\d+", text)
            if len(numbers) >= 2:
                point = tuple(map(int, numbers[:2]))
    elif isinstance(action, (tuple, list)) and action:
        name = str(action[0]).upper()
        if name == "MOUSE":
            if len(action) >= 3:
                point = int(action[1]), int(action[2])
            elif len(action) == 2:
                point = tuple(map(int, action[1]))
    else:
        name = str(action).upper()

    initial_layout = b[29][11] == "p" and b[35][23] == "Y"
    white_layout = b[5][20] == "W" and b[11][35] == "Y"
    if (
        (name == "LEFT" and initial_layout)
        or (name == "RIGHT" and white_layout)
    ):
        b = [["O"] * 64 for _ in range(64)]
        b[0][16:48] = ["c"] * 32
        paint(green, (14, 8))
        paint(yellow, (11, 32), "c")
        paint(purple, (29, 29), "c")
        return result()

    gp = find(green)
    yp = find_active_yellow()
    pp = find(purple)

    if name == "RIGHT" and gp is not None:
        joins_yellow = (
            gp == (14, 17)
            and b[14][32] == "c"
            and b[14][35] == "c"
        )
        if move(green, gp, 0, 3):
            if joins_yellow:
                for r in range(14, 17):
                    b[r][32:35] = ["G"] * 3
                b[0][17] = "W"
            elif gp == (14, 14) and yp is not None:
                b[0][18] = "W"
        return result()

    if name == "DOWN":
        if yp is not None:
            move(yellow, yp, 3, 0)
        elif gp is None:
            b[0][16] = "W"
        return result()

    if name == "LEFT":
        if yp is not None:
            move(yellow, yp, 0, -3)
        return result()

    if name != "MOUSE" or point is None:
        return result()

    if gp is not None and contains(green, gp, point):
        paint(green, gp, "c", preserve_join=True)
        return result()

    gi = find(green, inactive=True)
    if gi is not None and contains(green, gi, point):
        if pp is not None:
            paint(purple, pp, "c", preserve_join=True)
        paint(green, gi, preserve_join=True)
        if pp is None:
            b[0][16] = "W"
        return result()

    yi = find(yellow, inactive=True)
    if yi is None and b[11][47] == "c" and b[14][35] == "c":
        yi = (11, 32)
    if yi is not None and contains(yellow, yi, point):
        if gp is not None:
            paint(green, gp, "c", preserve_join=True)
        if pp is not None:
            paint(purple, pp, "c", preserve_join=True)
        paint(yellow, yi, preserve_join=True)
        return result()

    pi = find(purple, inactive=True)
    if pi is not None and contains(purple, pi, point):
        if yp is not None:
            paint(yellow, yp, "c", preserve_join=True)
            b[0][17] = "W"
        paint(purple, pi, preserve_join=True)
        return result()

    return result()
