import re


def _tiles(rows):
    """Rows of (pixel_row, [(pixel_column, color), ...])."""
    return {
        (r, c): color
        for r, entries in rows
        for c, color in entries
    }


_GREEN = _tiles([
    (5, [(5, "N"), (8, "N"), (11, "N"), (14, "N"), (17, "N")]),
    (8, [(5, "N"), (17, "N")]),
    (11, [(5, "N"), (17, "R")]),
    (14, [(5, "N")]),
    (17, [(5, "N"), (8, "N"), (11, "R")]),
    (20, [(5, "R")]),
])

_ORANGE = _tiles([
    (5, [(47, "O"), (50, "O"), (53, "O"), (56, "O")]),
    (8, [(47, "O"), (56, "O")]),
    (11, [(47, "R"), (56, "O")]),
    (14, [(53, "R"), (56, "O")]),
])

_SKY = _tiles([
    (38, [(5, "R")]),
    (41, [(5, "S")]),
    (44, [(5, "S")]),
    (47, [(5, "S")]),
    (50, [(5, "S")]),
    (53, [(5, "S"), (8, "R")]),
])


def _yellow(phase):
    d = _tiles([
        (20, [(26, "R")]),
        (23, [(23, "Y"), (26, "Y")]),
        (26, [(20, "R"), (23, "Y")]),
        (29, [(23, "Y")]),
        (32, [(23, "W")]),
    ])
    if phase >= 1:
        d.update({
            (32, 23): "Y", (32, 26): "Y",
            (32, 29): "W", (35, 23): "R",
        })
    if phase >= 2:
        d.update({
            (32, 29): "Y", (32, 32): "Y", (32, 35): "W",
        })
    if phase >= 3:
        d.update({
            (32, 35): "Y", (32, 38): "Y",
            (29, 38): "W", (35, 38): "R",
        })
    if phase >= 4:
        d.update({
            (29, 38): "Y", (26, 38): "Y", (23, 38): "W",
        })
    if phase >= 5:
        d.update({
            (23, 38): "Y", (20, 38): "Y",
            (20, 35): "R", (23, 41): "R",
        })
    return d


def _purple(phase):
    shift = 3 * phase
    d = _tiles([
        (44, [(35, "R")]),
        (47, [(35, "p")]),
        (50, [(32, "p"), (35, "p")]),
        (53, [(29, "R"), (32, "p")]),
    ])
    d[(44, 41 + shift)] = "R"
    d[(47, 41 + shift)] = "p"
    d[(50, 41 + shift)] = "p"
    d[(50, 44 + shift)] = "p"
    d[(53, 44 + shift)] = "p"
    for c in range(32, 45 + shift, 3):
        d[(56, c)] = "p"
    if phase < 3:
        d[(56, 38 + shift)] = "W"
    return d


def _paint(board, tiles, override=None):
    for (r, c), color in tiles.items():
        color = color if override is None else override
        for rr in range(r, r + 3):
            for cc in range(c, c + 3):
                board[rr][cc] = color


def _contains(tiles, r, c):
    return any(
        rr <= r < rr + 3 and cc <= c < cc + 3
        for rr, cc in tiles
    )


def _mouse_coordinates(action):
    if isinstance(action, (tuple, list)):
        if len(action) == 3 and str(action[0]).upper() == "MOUSE":
            return int(action[1]), int(action[2])
        return None
    text = str(action)
    if text.upper().startswith("MOUSE"):
        numbers = re.findall(r"-?\d+", text)
        if len(numbers) >= 2:
            return int(numbers[0]), int(numbers[1])
    return None


def predict(board_lines, action):
    """Return a complete 64x64 board; no mutable history is used."""
    b = [list(line) for line in board_lines]
    name = str(action).strip().upper()

    # Reconstruct the blue scene from the objects exposed in the trace.
    if name == "LEFT" and b[1][0] == "p":
        b = [["b"] * 64 for _ in range(64)]
        for c in range(16, 48):
            b[0][c] = "c"
        for shape in (_ORANGE, _yellow(0), _SKY, _purple(0)):
            _paint(b, shape, "c")
        _paint(b, _GREEN)
        return ["".join(row) for row in b]

    # Do not apply blue-scene rules to other scenes.
    if b[1][0] != "b":
        return ["".join(row) for row in b]

    mouse = _mouse_coordinates(action)
    if mouse is not None:
        r, c = mouse
        if not (0 <= r < 64 and 0 <= c < 64):
            return ["".join(row) for row in b]
        if b[r][c] == "b" or r == 0:
            return ["".join(row) for row in b]

        shapes = [
            ("green", _GREEN),
            ("orange", _ORANGE),
            ("yellow", _yellow(0)),
            ("sky", _SKY),
            ("purple", _purple(0)),
        ]
        selected = next(
            ((key, shape) for key, shape in shapes
             if _contains(shape, r, c)),
            None,
        )
        if selected is None:
            return ["".join(row) for row in b]

        key, shape = selected

        # Preserve the geometry of the object being deselected.
        for rr in range(1, 64):
            for cc in range(64):
                if b[rr][cc] not in ("b", "c"):
                    b[rr][cc] = "c"

