    """Model of the supplied ka59 observations.

    The 18 fully specified transitions are implemented directly.
    The two truncated redraws use the observed outline and an explicitly
    provisional rectangular gray mask. Their undisclosed remainder
    cannot be guaranteed cell-exact.
    """
    import re

    if len(board_lines) != 64 or any(len(row) != 64 for row in board_lines):
        raise ValueError("Expected 64 strings of length 64")

    board = list(board_lines)

    def normalize_action(value):
        if isinstance(value, str):
            text = value.strip().upper()
            if text.startswith("MOUSE"):
                numbers = re.findall(r"-?\d+", text)
                if len(numbers) == 2:
                    return ("MOUSE", int(numbers[0]), int(numbers[1]))
            return text
        if isinstance(value, (tuple, list)) and len(value) == 3:
            if str(value[0]).upper() == "MOUSE":
                return ("MOUSE", int(value[1]), int(value[2]))
        return value

    action = normalize_action(action)

    NORMAL = ("NNN", "NWN", "NNN")
    BLACK = ("NNN", "NBN", "NNN")
    BOTTOM = ("NNN", "NWN", "WWW")
    LEFT_EDGE = ("WNN", "WWN", "WNN")
    CORNER = ("WWW", "WWN", "WNN")

    rules = []

    def put(patch, row, col, old, new):
        if old != new:
            patch[(row, col)] = (old, new)

    def status(patch, col):
        put(patch, 63, col, "c", "W")

    def move(patch, old_center, new_center,
             old_sprite=NORMAL, new_sprite=NORMAL):
        row, col = old_center
        new_row, new_col = new_center
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                put(
                    patch, row + dr, col + dc,
                    old_sprite[dr + 1][dc + 1], "w"
                )
                put(
                    patch, new_row + dr, new_col + dc,
                    "w", new_sprite[dr + 1][dc + 1]
                )

    def repaint(patch, center, old_sprite, new_sprite):
        row, col = center
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                put(
                    patch, row + dr, col + dc,
                    old_sprite[dr + 1][dc + 1],
                    new_sprite[dr + 1][dc + 1]
                )

    def add(required_action, patch, guards=()):
        rules.append((required_action, patch, tuple(guards)))

    # Transition 1.
    patch = {}
    move(patch, (30, 21), (30, 24))
    status(patch, 63)
    add("RIGHT", patch)

    # Transition 2.
    patch = {}
    move(patch, (30, 24), (30, 27))
    add("RIGHT", patch)

    # Transition 3.
    patch = {}
    move(patch, (30, 27), (30, 30), new_sprite=BOTTOM)
    status(patch, 62)
    add("RIGHT", patch)

    # Transition 4.
    patch = {}
    repaint(patch, (30, 30), BOTTOM, NORMAL)
    move(patch, (33, 30), (48, 30), BLACK, BLACK)
    add("DOWN", patch, ((30, 30, "W"),))

    # Transition 6.
    patch = {}
    put(patch, 30, 30, "W", "c")
    put(patch, 48, 30, "B", "W")
    status(patch, 61)
    add(("MOUSE", 48, 30), patch)

    # Transition 7.
    patch = {}
    move(patch, (30, 21), (33, 21))
    status(patch, 63)
    add("DOWN", patch)

    # Transition 8.
    patch = {}
    move(patch, (48, 30), (51, 30))
    add("DOWN", patch)

    # Transition 9.
    patch = {}
    move(patch, (33, 21), (36, 21))
    add("DOWN", patch)

    # Transition 10.
    patch = {}
    move(patch, (51, 30), (54, 30), new_sprite=LEFT_EDGE)
    status(patch, 60)
    add("DOWN", patch)

    # Transition 11.
    patch = {}
    status(patch, 62)
    guards = tuple(
        (36 + dr, 21 + dc, NORMAL[dr + 1][dc + 1])
        for dr in range(-1, 2)
        for dc in range(-1, 2)
    )
    add("DOWN", patch, guards)

    # Transition 12.
    patch = {}
    move(patch, (54, 30), (57, 30), old_sprite=LEFT_EDGE)
    add("DOWN", patch)

    # Transition 13.
    patch = {}
    put(patch, 33, 30, "B", "W")
    put(patch, 36, 21, "W", "c")
    add(("MOUSE", 33, 30), patch)

    # Transition 14.
    patch = {}
    move(patch, (57, 30), (57, 27), new_sprite=CORNER)
    status(patch, 59)
    add("LEFT", patch)

    # Transition 15.
    patch = {}
    move(patch, (33, 30), (33, 27))
    status(patch, 61)
    add("LEFT", patch)

    # Transition 16.
    patch = {}
    for dr in range(-4, 5):
        for dc in range(-4, 5):
            if abs(dr) <= 1 or abs(dc) <= 1:
                put(patch, 54 + dr, 24 + dc, "Y", "w")
                put(patch, 33 + dr, 24 + dc, "w", "Y")
    repaint(patch, (57, 27), CORNER, NORMAL)
    add("UP", patch)

    # Transition 17.
    patch = {}
    move(patch, (33, 27), (33, 24))
    add("LEFT", patch)

