    status(patch, 60)
    add("LEFT", patch)

    def matches(patch, guards=()):
        return (
            all(
                board[row][col] == old
                for (row, col), (old, new) in patch.items()
            )
            and all(
                board[row][col] == expected
                for row, col, expected in guards
            )
        )

    def apply(patch):
        result = [list(row) for row in board]
        for (row, col), (old, new) in patch.items():
            result[row][col] = new
        return ["".join(row) for row in result]

    for required_action, patch, guards in rules:
        if action == required_action and matches(patch, guards):
            return apply(patch)

    # Recognize the common disclosed source signature of redraws 0 and 5.
    # Keep recognition separate from destination painting: the new gray
    # mask must overwrite objects, not merely light-gray pixels.
    if action in ("UP", "RIGHT"):
        signature = {}

        for col in range(5, 59):
