        for row in range(6, 17):
            for col in range(5, 33):
                put(signature, row, col, "w", "g")

        for col in range(5, 8):
            put(signature, 17, col, "w", "g")

        outline_prefix = {
            7: tuple(range(37, 42)),
            8: (37, 41),
            9: (37, 41),
            10: (34, 35, 36, 37, 41, 42, 43, 44),
            11: (34, 44),
            12: (34, 44),
            13: (34, 44),
            14: (34, 35, 36, 37, 41, 42, 43, 44),
            15: (37, 41),
            16: (37, 41),
        }

        for row, columns in outline_prefix.items():
            for col in columns:
                put(signature, row, col, "w", "c")

        if matches(signature):
            result = [list(row) for row in board]

            # Confirmed top strip.
            for col in range(5, 59):
                result[5][col] = "g"

            # Spatial-mask hypothesis. The continuation through row 19
            # is supported by feedback; the lower edge at 26 is inferred.
            for row in range(6, 27):
                for col in range(5, 33):
                    result[row][col] = "g"

            # Complete observed cross perimeter.
            outline = dict(outline_prefix)
            outline[17] = tuple(range(37, 42))
            for row, columns in outline.items():
                for col in columns:
                    result[row][col] = "c"

            # Other redraw content is undisclosed and is preserved.
            return ["".join(row) for row in result]

    return board
