            for c in range(7, 56):
                if b[r][c] == "S":
                    b[r][c] = "Y"
        draw_symbol(0, 0)
        draw_symbol(1, 6)
        draw_symbol(2, 4)
        put_bracket(0)
        b[63] = ["w"] * 64
        return ["".join(row) for row in b]

    selected = None
    for slot in range(7):
        left = 8 + 7 * slot
        if all(b[48][c] == "W" for c in range(left, left + 5)):
            selected = slot
            break

    if selected is None:
        return ["".join(row) for row in b]

    # Recover the half-tick phase for all recorded input states.
    cadence = {}
    sequence = (
        ["DOWN"] * 7
        + ["UP"] * 3
        + ["RIGHT"]
        + ["UP"] * 3
        + ["RIGHT"]
        + ["UP"] * 3
        + ["RIGHT"]
    )
    nums = [0, 6, 4]
    cursor = 0
    consumed = 0

    for step, recorded_action in enumerate(sequence, 1):
        key = (tuple(nums), cursor, consumed, recorded_action)
        cadence[key] = (step % 2 == 0)

        if recorded_action == "RIGHT":
            cursor += 1
        elif recorded_action == "DOWN":
            nums[cursor] = (nums[cursor] + 1) % 7
        elif recorded_action == "UP":
            nums[cursor] = (nums[cursor] - 1) % 7

        if step % 2 == 0:
            consumed += 1

    visible_nums = tuple(read_symbol(i) for i in range(3))
    consumed = 0
    for c in range(63, -1, -1):
        if b[63][c] != "c":
            break
        consumed += 1

    tick = cadence.get(
        (visible_nums, selected, consumed, a), False
    )

    if a in ("UP", "DOWN"):
        number = read_symbol(selected)
        if number is not None:
            left = 8 + 7 * selected
            color = b[51][left]
            if color not in ("Y", "S", "P"):
                color = "Y"
            delta = 1 if a == "DOWN" else -1
            draw_symbol(selected, (number + delta) % 7, color)

    elif a == "RIGHT":
        put_bracket(min(6, selected + 1))

    elif a == "LEFT":
        put_bracket(max(0, selected - 1))

    if tick:
        for c in range(63, -1, -1):
            if b[63][c] == "w":
                b[63][c] = "c"
                break

    return ["".join(row) for row in b]
