def predict(board_lines, action):
    board = [list(row) for row in board_lines]
    if len(board) != 64 or any(len(row) != 64 for row in board):
        raise ValueError("Expected 64 strings of length 64")

    directions = {
        "UP": (-6, 0),
        "DOWN": (6, 0),
        "LEFT": (0, -6),
        "RIGHT": (0, 6),
    }
    marker_offsets = {
        "UP": (0, 1),
        "DOWN": (2, 1),
        "LEFT": (1, 0),
        "RIGHT": (1, 2),
    }

    def finish():
        return ["".join(row) for row in board]

    def square(r, c, color):
        for y in range(r, r + 3):
            for x in range(c, c + 3):
                board[y][x] = color

    def piece(r, c, color, marker, facing):
        square(r, c, color)
        dy, dx = marker_offsets[facing]
        board[r + dy][c + dx] = marker

    def anchors(color):
        return sorted({
            (r // 3 * 3, c // 3 * 3)
            for r in range(63)
            for c in range(64)
            if board[r][c] == color
        })

    def facing_at(r, c, marker):
        for facing, (dy, dx) in marker_offsets.items():
            if board[r + dy][c + dx] == marker:
                return facing
        return None

    def connected(r, c, nr, nc):
        if not (0 <= nr <= 60 and 0 <= nc <= 61):
            return False
        mr, mc = (r + nr) // 2, (c + nc) // 2
        return board[mr + 1][mc + 1] == "g"

    def horizontal_nodes(r, first, last):
        for c in range(first, last + 1, 3):
            color = "W" if (c - first) % 6 == 0 else "g"
            square(r, c, color)

    def load_scene():
        nonlocal board
        board = [["B"] * 64 for _ in range(64)]

        for r, first, last in (
            (18, 24, 36),
            (24, 24, 48),
            (30, 12, 48),
            (36, 12, 18),
            (36, 30, 42),
            (42, 18, 24),
        ):
            horizontal_nodes(r, first, last)

