    """Return the complete next board as 64 strings of 64 characters."""
    board = [list(row) for row in board_lines]

    directions = {
        "UP": (-1, 0),
        "DOWN": (1, 0),
        "LEFT": (0, -1),
        "RIGHT": (0, 1),
    }
    markers = {
        "UP": (0, 1),
        "DOWN": (2, 1),
        "LEFT": (1, 0),
        "RIGHT": (1, 2),
    }

    def finish():
        return ["".join(row) for row in board]

    if not isinstance(action, str) or action not in directions:
        return finish()

    def square(pos, color, marker=None, facing=None):
        r, c = pos
        for dr in range(3):
            for dc in range(3):
                board[r + dr][c + dc] = color
        if marker is not None:
            dr, dc = markers[facing]
            board[r + dr][c + dc] = marker

    def locate(color):
        cells = [
            (r, c)
            for r in range(63)
            for c in range(64)
            if board[r][c] == color
        ]
        if not cells:
            return None
        return min(r for r, c in cells), min(c for r, c in cells)

    def replacement_level():
        for r in range(64):
            board[r][:] = ["B"] * 64

        nodes = {
            (14, 26), (14, 32), (14, 38),
            (20, 38), (26, 38),
            (32, 20), (32, 26), (32, 32),
            (32, 38), (32, 44),
            (38, 20), (38, 26),
            (44, 14), (44, 20), (44, 26),
        }
        forbidden = frozenset(((38, 20), (38, 26)))

        for r, c in nodes:
            square((r, c), "W")
            for dr, dc in ((1, 0), (0, 1)):
                other = (r + 6 * dr, c + 6 * dc)
                if other not in nodes:
                    continue
                if frozenset(((r, c), other)) == forbidden:
                    continue
                for i in range(3):
                    for j in range(3):
                        board[r + 3 * dr + i][c + 3 * dc + j] = "g"

        square((14, 26), "N")
        square((20, 38), "r", "p", "DOWN")
        square((32, 20), "R", "p", "DOWN")
        square((44, 14), "b", "c", "RIGHT")
        board[63][:] = ["M"] * 64

    def spend_action():
        length = board[63].count("M")
        candidates = [
            n for n in range(51)
            if max(0, round(64 - 1.28 * n)) == length
        ]
        if candidates:
            next_count = candidates[0] + 1
            remaining = max(0, round(64 - 1.28 * next_count))
        else:
            remaining = max(0, length - 1)
        board[63][:] = ["M"] * remaining + ["W"] * (64 - remaining)

    def neighbors(pos):
        r, c = pos
        result = []
        for name in ("UP", "DOWN", "LEFT", "RIGHT"):
            dr, dc = directions[name]
            nr, nc = r + 6 * dr, c + 6 * dc
            if not (0 <= nr <= 60 and 0 <= nc <= 61):
                continue

            er, ec = r + 1 + 3 * dr, c + 1 + 3 * dc
            if board[er][ec] != "g":
                continue
            if board[nr + 1][nc + 1] in ("B", "g"):
                continue
            result.append((name, (nr, nc)))
        return result

