        queue = deque([start])
        previous = {start: None}
        while queue:
            current = queue.popleft()
            if current == goal:
                route = []
                while previous[current] is not None:
                    parent, name = previous[current]
                    route.append((name, current))
                    current = parent
                route.reverse()
                return route

            for name, nxt in neighbors(current):
