            value = board[er + mr][ec + mc]
            if value == "Y":
                active_facing = name
            elif value == "p":
                dormant_facing = name

    square(player, "W")
    square(target, "b", "c", action)

    if enemy is not None:
        if active_facing is not None:
            # Advance using the previously committed direction,
            # not a newly computed shortest path.
            next_enemy = dict(neighbors(enemy)).get(active_facing)
            if next_enemy is not None:
                square(enemy, "W")
                route = path_between(next_enemy, target)
                next_facing = route[0][0] if route else active_facing
                square(next_enemy, "r", "Y", next_facing)

        elif dormant_facing is not None:
            route = path_between(enemy, target)
            if (
                route
                and len(route) <= 2
                and all(name == dormant_facing for name, _ in route)
            ):
                square(enemy, "r", "Y", dormant_facing)

    spend_action()
    return finish()

